import React,{useEffect,useMemo,useState} from 'react'
import {createRoot} from 'react-dom/client'
import axios from 'axios'
import {QRCodeSVG} from 'qrcode.react'
import './styles.css'

const API=import.meta.env.VITE_API_URL || ((location.hostname==='localhost'||location.hostname==='127.0.0.1')?'http://localhost:8000/api':'/api')
const api=axios.create({baseURL:API})
const money=v=>Number(v||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'})
const fmtDate=v=>v?new Date(v).toLocaleDateString('pt-BR'):'—'
function setToken(t){localStorage.setItem('token',t);api.defaults.headers.common.Authorization=`Bearer ${t}`}
function logout(){localStorage.removeItem('token');location.href='/'}

const MENU=[
 {key:'dashboard',icon:'▦',label:'Dashboard'},
 {key:'qrcode',icon:'⌗',label:'QR Code'},
 {key:'cadastros',icon:'▣',label:'Cadastros',children:[
   {key:'vehicle-create',icon:'▰',label:'Cadastro de Sucatas'},
   {key:'product-create',icon:'⚙',label:'Cadastro de Peças'},
   {key:'part-groups',icon:'◆',label:'Grupo de peças'},
   {key:'customers',icon:'♣',label:'Clientes'},
   {key:'locations',icon:'●',label:'Localizações'},
   {key:'carriers',icon:'▰',label:'Transportadoras'},
   {key:'sellers',icon:'♟',label:'Vendedores'},
   {key:'suppliers',icon:'♙',label:'Fornecedores'},
   {key:'tax',icon:'⌁',label:'Configuração Tributária'}
 ]},
 {key:'products',icon:'▤',label:'Estoque de peças'},
 {key:'vehicles',icon:'▱',label:'Sucatas'},
 {key:'etiquetas',icon:'◇',label:'Etiquetas',children:[
   {key:'labels',label:'Gerar etiquetas'},
   {key:'label-models',label:'Modelos de etiqueta'}
 ]},
 {key:'integracoes',icon:'◈',label:'Integrações',children:[
   {key:'marketplaces',label:'Central de integrações'},
   {key:'mercadolivre',label:'Mercado Livre'},
   {key:'shopee',label:'Shopee'},
   {key:'olx',label:'OLX'}
 ]},
 {key:'compras',icon:'▾',label:'Compras',children:[
   {key:'purchase-new',label:'Nova Compra'},
   {key:'purchases',label:'Compras Realizadas'}
 ]},
 {key:'vendas',icon:'$',label:'Vendas',children:[
   {key:'sales',label:'Nova Venda'},
   {key:'sales-history',label:'Vendas Realizadas'},
   {key:'shipping',label:'Painel de Expedição'}
 ]},
 {key:'notas',icon:'▧',label:'Notas Fiscais',children:[
   {key:'invoices',label:'NF-e'},
   {key:'invoice-history',label:'Notas Emitidas'},
   {key:'xml',label:'Enviar XML'},
   {key:'invalidate-number',label:'Inutilizar número'}
 ]},
 {key:'finance',icon:'◉',label:'Financeiro'},
 {key:'subscription',icon:'R$',label:'Assinatura'},
 {key:'cashflow',icon:'⇆',label:'Fluxo de Caixa'},
 {key:'reports',icon:'▥',label:'Relatórios'},
 {key:'gamification',icon:'✦',label:'Gamificação'}
]
const TITLE_MAP={company:'Informações da Empresa'}
MENU.forEach(item=>{TITLE_MAP[item.key]=item.label;(item.children||[]).forEach(c=>TITLE_MAP[c.key]=c.label)})

function App(){
 const [logged,setLogged]=useState(!!localStorage.getItem('token'))
 const [tab,setTab]=useState('dashboard')
 const [theme,setTheme]=useState(localStorage.getItem('theme')||'dark')
 const [session,setSession]=useState(null)
 const [vehicles,setVehicles]=useState([]),[products,setProducts]=useState([]),[sales,setSales]=useState([]),[finance,setFinance]=useState([]),[marketplaces,setMarketplaces]=useState([]),[listings,setListings]=useState([])
 const [vehicleBrands,setVehicleBrands]=useState([]),[billing,setBilling]=useState({monthly_price:350,checkout_provider_configured:false})
 const [catalog,setCatalog]=useState({customers:[],suppliers:[],carriers:[],sellers:[],partGroups:[],locations:[],users:[],tax:null})
 const [toast,setToast]=useState('')
 useEffect(()=>{document.body.dataset.theme=theme;localStorage.setItem('theme',theme)},[theme])
 useEffect(()=>{const t=localStorage.getItem('token');if(t)api.defaults.headers.common.Authorization=`Bearer ${t}`},[])
 async function load(){
   try{
     const [me,bi]=await Promise.all([api.get('/auth/me'),api.get('/billing/status')])
     setSession(me.data);setBilling(bi.data||{})
     if(bi.data?.active===false){
       setVehicles([]);setProducts([]);setSales([]);setFinance([]);setMarketplaces([]);setListings([])
       return
     }
     const [v,p,s,f,m,l,cu,su,ca,se,pg,lo,us,tx,vb]=await Promise.all([
       api.get('/vehicles'),api.get('/products'),api.get('/sales'),api.get('/finance'),api.get('/marketplaces/status'),api.get('/marketplaces/listings'),
       api.get('/catalog/customers'),api.get('/catalog/suppliers'),api.get('/catalog/carriers'),api.get('/catalog/sellers'),api.get('/catalog/part-groups'),api.get('/catalog/locations'),api.get('/catalog/users'),api.get('/catalog/tax'),api.get('/vehicle-catalog/brands')
     ])
     setVehicles(v.data);setProducts(p.data);setSales(s.data);setFinance(f.data);setMarketplaces(m.data);setListings(l.data)
     setVehicleBrands(vb.data.brands||[])
     setCatalog({customers:cu.data,suppliers:su.data,carriers:ca.data,sellers:se.data,partGroups:pg.data,locations:lo.data,users:us.data,tax:tx.data})
   }catch(e){if(e.response?.status===401){logout()}else if(e.response?.status===402){setBilling(b=>({...b,active:false}))}else console.error(e)}
 }
 useEffect(()=>{if(logged)load()},[logged])
 useEffect(()=>{const q=new URLSearchParams(location.search);const integration=q.get('integration');const status=q.get('status');if(integration){setTab('marketplaces');setTimeout(()=>notice(status==='connected'?`${marketName(integration)} conectado com sucesso`:`Não foi possível conectar ${marketName(integration)}`),300);history.replaceState({},'',location.pathname)}},[])
 function notice(t){setToast(t);setTimeout(()=>setToast(''),3800)}
 if(!logged)return <Login onLogin={r=>{setToken(r.access_token);setSession(r);setLogged(true)}}/>
 const accessBlocked=!!session&&billing?.active===false
 return <div className="appShell">
   <Sidebar tab={tab} setTab={setTab} company={session?.company}/>
   <main className="mainArea">
     <Topbar tab={tab} setTab={setTab} session={session} theme={theme} setTheme={setTheme}/>
     <div className="content">
       {accessBlocked?<BillingPage billing={billing} session={session} refresh={load} notice={notice}/>:<>
       {tab==='dashboard'&&<Dashboard v={vehicles} p={products} s={sales} f={finance} marketplaces={marketplaces} session={session}/>} 
       {tab==='company'&&<CompanyInfo session={session} reload={load} notice={notice}/>} 
       {tab==='qrcode'&&<QRCodeModule products={products}/>} 
       {tab==='vehicle-create'&&<Vehicles data={vehicles} refresh={load} notice={notice} brands={vehicleBrands} createOnly/>}
       {tab==='vehicles'&&<Vehicles data={vehicles} refresh={load} notice={notice} brands={vehicleBrands}/>} 
       {tab==='product-create'&&<ProductForm refresh={load} notice={notice} groups={catalog.partGroups} brands={vehicleBrands} vehicles={vehicles}/>} 
       {tab==='products'&&<Inventory data={products} listings={listings} refresh={load} notice={notice} groups={catalog.partGroups} brands={vehicleBrands} vehicles={vehicles} company={session?.company}/>} 
       {['customers','suppliers','carriers','sellers','part-groups','locations','tax'].includes(tab)&&<CatalogModule tab={tab} data={catalog} refresh={load} notice={notice}/>} 
       {tab==='cadastros'&&<CadastrosHome setTab={setTab}/>} 
       {['labels','label-models','etiquetas'].includes(tab)&&<LabelsModule tab={tab} products={products} company={session?.company}/>} 
       {tab==='sales'&&<Sales products={products} sales={sales} refresh={load} notice={notice}/>} 
       {tab==='sales-history'&&<SalesHistory sales={sales}/>} 
       {tab==='shipping'&&<SimpleModule eyebrow="EXPEDIÇÃO" title="Painel de Expedição" text="Separe, confira e acompanhe pedidos que precisam ser enviados." actions={['Aguardando separação','Prontos para envio','Despachados']}/>} 
       {['marketplaces','mercadolivre','shopee','olx','integracoes'].includes(tab)&&<Marketplaces data={marketplaces} listings={listings} products={products} refresh={load} notice={notice} focus={tab} subscription={session?.subscription}/>} 
       {['purchase-new','purchases','compras'].includes(tab)&&<SimpleModule eyebrow="COMPRAS" title={tab==='purchase-new'?'Nova Compra':'Compras'} text="Controle pedidos de compra, fornecedores, custos e recebimentos." actions={['Novo pedido de compra','Compras realizadas','Recebimentos']}/>} 
       {['invoices','invoice-history','xml','invalidate-number','notas'].includes(tab)&&<FiscalModule tab={tab}/>} 
       {tab==='finance'&&<Finance data={finance} refresh={load} notice={notice}/>} 
       {tab==='subscription'&&<BillingPage billing={billing} session={session} refresh={load} notice={notice}/>} 
       {tab==='cashflow'&&<CashFlow data={finance}/>} 
       {tab==='reports'&&<Reports products={products} sales={sales} finance={finance} vehicles={vehicles}/>} 
       {tab==='gamification'&&<Gamification sales={sales} products={products}/>} 
       </>}
     </div>
   </main>
   {toast&&<div className="toast">✓ {toast}</div>}
 </div>
}

function Sidebar({tab,setTab,company}){
 const [open,setOpen]=useState({cadastros:true,etiquetas:false,integracoes:false,compras:false,vendas:true,notas:true})
 function isActive(item){return tab===item.key||(item.children||[]).some(c=>c.key===tab)}
 return <aside className="sidebar">
   <div className="brand"><div className="brandMark">CDM</div><div><h1>{company?.trade_name||'CDM Desmontes'}</h1><small>ERP de autopeças</small></div></div>
   <nav className="sideNav">{MENU.map(item=>item.children?
     <div className={'navGroup '+(isActive(item)?'activeGroup':'')} key={item.key}>
       <button className={'navMain '+(isActive(item)?'active':'')} onClick={()=>setOpen({...open,[item.key]:!open[item.key]})}><span className="navIcon">{item.icon}</span><span className="navLabel">{item.label}</span><span className={'chevron '+(open[item.key]?'open':'')}>⌄</span></button>
       {open[item.key]&&<div className="subNav">{item.children.map(c=><button key={c.key} className={tab===c.key?'active':''} onClick={()=>setTab(c.key)}><span>{c.icon||'·'}</span>{c.label}</button>)}</div>}
     </div>
     :<button key={item.key} className={'navMain '+(tab===item.key?'active':'')} onClick={()=>setTab(item.key)}><span className="navIcon">{item.icon}</span><span className="navLabel">{item.label}</span></button>)}</nav>
   <div className="sidebarFoot"><span><i/> Sistema online</span><small>CDM Desmontes SaaS</small></div>
 </aside>
}

function Topbar({tab,setTab,session,theme,setTheme}){
 const [profile,setProfile]=useState(false),[query,setQuery]=useState('')
 const sub=session?.subscription
 return <header className="topbar">
   <button className="hamb">☰</button>
   <div className="globalSearch">⌕<input value={query} onChange={e=>setQuery(e.target.value)} onKeyDown={e=>{if(e.key==='Enter')setTab('products')}} placeholder="O que você está procurando?"/></div>
   <button className="topAdd" onClick={()=>setTab('product-create')}>＋</button>
   <div className="topSpacer"/>
   <button className="topIcon" title="Notas fiscais" onClick={()=>setTab('invoice-history')}>▤</button>
   <button className="topIcon" title="Notificações">♢</button>
   <button className="topIcon" title="Compras" onClick={()=>setTab('purchases')}>🛒</button>
   <div className="profileWrap"><button className="profileButton" onClick={()=>setProfile(!profile)}>● <span>⌄</span></button>
     {profile&&<div className="profileMenu">
       <div className="profileHead"><div className="avatar">{(session?.user?.name||'U').slice(0,1).toUpperCase()}</div><div><b>{session?.user?.email}</b><small>{session?.user?.role==='owner'?'Administrador':'Usuário'}</small></div></div>
       <button onClick={()=>{setTab('company');setProfile(false)}}>▦ <span>Informações da Empresa</span></button>
       <div className="themeRow"><span>◉ Alterar tema</span><div><button className={theme==='light'?'sel':''} onClick={()=>setTheme('light')}>☀</button><button className={theme==='dark'?'sel':''} onClick={()=>setTheme('dark')}>☾</button></div></div>
       <div className="subMini"><span>Plano {sub?.plan||'mensal'}</span><b className={['active','trial'].includes(sub?.status)?'ok':'bad'}>{sub?.status||'—'}</b></div>
       <button className="dangerText" onClick={logout}>↪ <span>Sair</span></button>
     </div>}
   </div>
 </header>
}

function Login({onLogin}){
 const [mode,setMode]=useState('login'),[err,setErr]=useState(''),[busy,setBusy]=useState(false)
 const [login,setLogin]=useState({email:'',password:''})
 const [reg,setReg]=useState({company_name:'',name:'',email:'',password:'',cnpj:'',phone:''})
 async function go(){setBusy(true);setErr('');try{if(mode==='login'){const r=await api.post('/auth/login',login);onLogin(r.data)}else{const r=await api.post('/auth/register',reg);onLogin(r.data)}}catch(e){setErr(e.response?.data?.detail||'Não foi possível continuar')}finally{setBusy(false)}}
 return <div className="loginPage"><section className="loginHero"><div className="heroLogo">CDM</div><span>CDM DESMONTES ERP</span><h1>Seu desmanche conectado a todos os canais.</h1><p>Estoque, sucatas, vendas, financeiro e publicação em marketplaces em uma única operação.</p><div className="loginBenefits"><span>✓ Multiempresa</span><span>✓ Mercado Livre, Shopee e OLX</span><span>✓ Controle por assinatura</span><span>✓ 7 dias grátis · depois R$ 350/mês</span></div></section><section className="loginBox"><div className="loginTabs"><button className={mode==='login'?'active':''} onClick={()=>setMode('login')}>Entrar</button><button className={mode==='register'?'active':''} onClick={()=>setMode('register')}>Criar conta</button></div>{mode==='login'?<><h2>Bem-vindo</h2><p>Acesse o painel da sua empresa.</p><Field label="E-mail"><input value={login.email} onChange={e=>setLogin({...login,email:e.target.value})}/></Field><Field label="Senha"><input type="password" value={login.password} onChange={e=>setLogin({...login,password:e.target.value})}/></Field></>:<><h2>Abra sua empresa no CDM</h2><p>O cliente cria a própria conta, testa por 7 dias e depois assina por R$ 350/mês. Os marketplaces são conectados pela própria empresa.</p><Field label="Nome da empresa"><input value={reg.company_name} onChange={e=>setReg({...reg,company_name:e.target.value})}/></Field><Field label="Seu nome"><input value={reg.name} onChange={e=>setReg({...reg,name:e.target.value})}/></Field><Field label="E-mail"><input value={reg.email} onChange={e=>setReg({...reg,email:e.target.value})}/></Field><Field label="Senha"><input type="password" value={reg.password} onChange={e=>setReg({...reg,password:e.target.value})}/></Field><div className="miniGrid"><Field label="CNPJ"><input value={reg.cnpj} onChange={e=>setReg({...reg,cnpj:e.target.value})}/></Field><Field label="Telefone"><input value={reg.phone} onChange={e=>setReg({...reg,phone:e.target.value})}/></Field></div></>}
 <button className="primary loginSubmit" disabled={busy} onClick={go}>{busy?'Aguarde...':mode==='login'?'Entrar no sistema →':'Criar minha conta →'}</button>{err&&<div className="error">{err}</div>}<small className="loginNote">Plano profissional: 7 dias de teste e depois R$ 350/mês. A cobrança recorrente é feita pelo Mercado Pago quando configurado no servidor.</small></section></div>
}

const Card=({icon,title,value,sub})=><div className="metric"><div className="metricIcon">{icon}</div><div><small>{title}</small><strong>{value}</strong><em>{sub}</em></div></div>
function Dashboard({v,p,s,f,marketplaces,session}){let receita=s.reduce((a,x)=>a+x.total,0),entr=f.filter(x=>x.kind==='income').reduce((a,x)=>a+x.amount,0),sai=f.filter(x=>x.kind==='expense').reduce((a,x)=>a+x.amount,0),stock=p.reduce((a,x)=>a+x.stock,0);return <><div className="pageTitle"><div><span>PAINEL OPERACIONAL</span><h2>{session?.company?.trade_name||'CDM Desmontes'}</h2><p>Acompanhe sua operação em tempo real.</p></div><div className="statusBadge">● Assinatura {session?.subscription?.status||'—'}</div></div><div className="grid metrics"><Card icon="🚗" title="Sucatas cadastradas" value={v.length} sub="Base de desmontagem"/><Card icon="⚙" title="Peças em estoque" value={stock} sub={`${p.length} SKUs cadastrados`}/><Card icon="↗" title="Faturamento" value={money(receita)} sub={`${s.length} vendas registradas`}/><Card icon="▣" title="Saldo financeiro" value={money(entr-sai)} sub="Entradas menos saídas"/></div><div className="twoCols"><section className="panel"><PanelHead eyebrow="OPERAÇÃO" title="Estoque recente" text="Últimos itens cadastrados"/><Table rows={p.slice(0,6)} cols={['sku','name','price','stock']} format={{price:money}}/></section><section className="panel"><PanelHead eyebrow="CANAIS" title="Marketplaces" text="Conexões da sua empresa"/><div className="channelList">{marketplaces.map(m=><div className="channel" key={m.id}><MarketLogo id={m.id}/><div><b>{marketName(m.id)}</b><small>{m.connected?(m.account_name||'Conta conectada'):'Aguardando autorização'}</small></div><span className={m.connected?'pill success':'pill warn'}>{m.connected?'Conectado':'Conectar'}</span></div>)}</div></section></div></>}

function CompanyInfo({session,reload,notice}){const empty={trade_name:'',legal_name:'',cnpj:'',state_registration:'',tax_regime:'Simples Nacional',email:'',phone:'',responsible_name:'',rg:'',cpf:'',issuing_agency:'',cep:'',state:'RJ',city:'',address:'',number:'',complement:'',logo_url:''};const [form,setForm]=useState({...empty,...(session?.company||{})});useEffect(()=>setForm({...empty,...(session?.company||{})}),[session]);async function save(){try{await api.put('/company/me',form);await reload();notice('Informações da empresa atualizadas')}catch(e){notice(e.response?.data?.detail||'Erro ao salvar')}}return <section className="panel companyPanel"><PanelHead eyebrow="EMPRESA" title="Informações da empresa" text="Esses dados pertencem somente a esta assinatura e também ajudam no envio para marketplaces."/><div className="companyGrid">{[['Nome Fantasia','trade_name'],['Razão Social','legal_name'],['CNPJ','cnpj'],['Inscrição Estadual','state_registration'],['Regime de Tributação','tax_regime'],['E-mail','email'],['Telefone','phone'],['Nome do Responsável','responsible_name'],['RG','rg'],['CPF','cpf'],['Órgão Expedidor','issuing_agency'],['CEP','cep'],['UF','state'],['Cidade','city'],['Endereço','address'],['Número','number'],['Complemento','complement']].map(([label,key])=><Field key={key} label={label}><input value={form[key]||''} onChange={e=>setForm({...form,[key]:e.target.value})}/></Field>)}</div><div className="subscriptionBox"><div><small>ASSINATURA</small><b>Plano {session?.subscription?.plan||'mensal'}</b><span>Status: {session?.subscription?.status||'—'} · vencimento {fmtDate(session?.subscription?.expires_at)}</span></div><span className={['active','trial'].includes(session?.subscription?.status)?'pill success':'pill warn'}>{session?.subscription?.status||'—'}</span></div><button className="primary" onClick={save}>Salvar informações</button></section>}

function BillingPage({billing,session,refresh,notice}){const price=Number(billing?.monthly_price||350);async function checkout(){try{const r=await api.post('/billing/checkout');if(!r.data.checkout_url)return notice('O Mercado Pago não retornou o link de pagamento');location.href=r.data.checkout_url}catch(e){notice(e.response?.data?.detail||'Não foi possível abrir a assinatura')}}async function sync(){try{await api.post('/billing/sync');await refresh();notice('Status da assinatura atualizado')}catch(e){notice(e.response?.data?.detail||'Não foi possível sincronizar')}}const active=['active','trial'].includes(session?.subscription?.status);return <><div className="pageTitle"><div><span>PLANO CDM</span><h2>Assinatura mensal</h2><p>Venda o acesso ao seu ERP por assinatura recorrente.</p></div><span className={active?'statusBadge':'statusBadge bad'}>{session?.subscription?.status||'—'}</span></div><div className="billingHero panel"><div><small>PLANO PROFISSIONAL</small><h2>{money(price)} <span>/ mês</span></h2><p>Uma empresa por assinatura, com usuários, estoque, veículos, vendas e integrações separados.</p><Checklist items={['7 dias de teste para novos cadastros','Cadastro de sucatas e peças','Mercado Livre, Shopee e OLX por empresa','Estoque, vendas e financeiro','Renovação mensal via Mercado Pago']}/></div><div className="billingAction"><span className={billing?.checkout_provider_configured?'pill success':'pill warn'}>{billing?.checkout_provider_configured?'Mercado Pago configurado':'Configure MP_ACCESS_TOKEN no Render'}</span><button className="primary bigBtn" disabled={!billing?.checkout_provider_configured} onClick={checkout}>Assinar por {money(price)} / mês →</button>{session?.subscription?.external_subscription_id&&<button className="ghost full" onClick={sync}>Atualizar status da assinatura</button>}<small>O cliente paga diretamente no checkout do Mercado Pago. O CDM nunca recebe a senha da conta bancária do cliente.</small></div></div></>}

function QRCodeModule({products}){const [pid,setPid]=useState(products[0]?.id||'');const p=products.find(x=>x.id===+pid);const value=p?`CDM|${p.id}|${p.sku}|${p.name}`:'CDM Desmontes';return <div className="twoCols"><section className="panel"><PanelHead eyebrow="IDENTIFICAÇÃO" title="QR Code" text="Gere um QR Code para localizar rapidamente uma peça."/><Field label="Peça"><select value={pid} onChange={e=>setPid(e.target.value)}><option value="">Selecione...</option>{products.map(x=><option key={x.id} value={x.id}>{x.sku} — {x.name}</option>)}</select></Field>{p&&<div className="qrCard"><QRCodeSVG value={value} size={180}/><div><small>SKU</small><strong>{p.sku}</strong><h3>{p.name}</h3><p>{p.brand} {p.model}</p></div></div>}</section><section className="panel"><PanelHead eyebrow="LEITURA" title="Uso no estoque" text="Identifique caixas, peças e prateleiras."/><Checklist items={['Identificação por SKU','Conferência de estoque','Separação para expedição','Impressão de etiquetas']}/></section></div>}

function CadastrosHome({setTab}){const cards=[['▰','Cadastro de Sucatas','vehicle-create'],['⚙','Cadastro de Peças','product-create'],['◆','Grupo de peças','part-groups'],['♣','Clientes','customers'],['●','Localizações','locations'],['▰','Transportadoras','carriers'],['♟','Vendedores','sellers'],['♙','Fornecedores','suppliers'],['⌁','Configuração Tributária','tax']];return <><div className="pageTitle"><div><span>BASE CADASTRAL</span><h2>Cadastros</h2><p>Organize todos os dados essenciais da operação.</p></div></div><div className="moduleCards">{cards.map(([i,t,k])=><button className="moduleCard clickable" key={k} onClick={()=>setTab(k)}><div className="moduleIcon">{i}</div><div><h3>{t}</h3><p>Abrir cadastro e gerenciamento.</p><span className="pill neutral">Acessar</span></div></button>)}</div></>}

function VehicleBrandModel({form,setForm,brands=[]}){const [models,setModels]=useState([]),[customModel,setCustomModel]=useState(false);useEffect(()=>{let active=true;setModels([]);if(!form.brand){return}api.get('/vehicle-catalog/models',{params:{brand:form.brand}}).then(r=>{if(active){setModels(r.data.models||[]);if(form.model&&!(r.data.models||[]).includes(form.model))setCustomModel(true)}}).catch(()=>setModels([]));return()=>{active=false}},[form.brand]);return <><Field label="Marca"><select value={form.brand||''} onChange={e=>{setForm({...form,brand:e.target.value,model:''});setCustomModel(false)}}><option value="">Selecione a marca...</option>{brands.map(b=><option key={b} value={b}>{b}</option>)}</select></Field><Field label="Modelo">{customModel?<div className="inlineInput"><input autoFocus value={form.model||''} onChange={e=>setForm({...form,model:e.target.value})} placeholder="Digite o modelo"/><button type="button" className="ghost mini" onClick={()=>{setCustomModel(false);setForm({...form,model:''})}}>Lista</button></div>:<select value={form.model||''} disabled={!form.brand} onChange={e=>{if(e.target.value==='__custom__'){setCustomModel(true);setForm({...form,model:''})}else setForm({...form,model:e.target.value})}}><option value="">{form.brand?'Selecione o modelo...':'Escolha a marca primeiro'}</option>{models.map(m=><option key={m} value={m}>{m}</option>)}<option value="__custom__">Outro / digitar manualmente...</option></select>}</Field></>}

function Vehicles({data,refresh,notice,brands=[],createOnly=false}){const [form,setForm]=useState({plate:'',brand:'',model:'',year:new Date().getFullYear(),vin:'',renavam:'',fuel:'Flex',transmission:'Automático',color:'',acquisition_value:0,other_costs:0});async function add(){try{await api.post('/vehicles',form);setForm({plate:'',brand:'',model:'',year:new Date().getFullYear(),vin:'',renavam:'',fuel:'Flex',transmission:'Automático',color:'',acquisition_value:0,other_costs:0});await refresh();notice('Sucata cadastrada')}catch(e){notice(e.response?.data?.detail||'Erro ao cadastrar')}}return <><section className="panel"><PanelHead eyebrow="DESMONTAGEM" title="Cadastro de Sucata / Veículo" text="Registre o veículo de origem. Marca e modelo já vêm organizados para acelerar o cadastro."/><div className="formGrid"><Field label="Placa"><input value={form.plate} onChange={e=>setForm({...form,plate:e.target.value.toUpperCase()})}/></Field><VehicleBrandModel form={form} setForm={setForm} brands={brands}/><Field label="Ano"><input type="number" min="1971" max={new Date().getFullYear()+1} value={form.year} onChange={e=>setForm({...form,year:+e.target.value})}/></Field><Field label="Chassi/VIN"><input value={form.vin} onChange={e=>setForm({...form,vin:e.target.value.toUpperCase()})}/></Field><Field label="Renavam"><input value={form.renavam} onChange={e=>setForm({...form,renavam:e.target.value})}/></Field><Field label="Combustível"><select value={form.fuel} onChange={e=>setForm({...form,fuel:e.target.value})}><option>Flex</option><option>Gasolina</option><option>Etanol</option><option>Diesel</option><option>Híbrido</option><option>Elétrico</option><option>GNV</option></select></Field><Field label="Câmbio"><select value={form.transmission} onChange={e=>setForm({...form,transmission:e.target.value})}><option>Automático</option><option>Manual</option><option>CVT</option><option>Automatizado</option></select></Field><Field label="Cor"><input value={form.color} onChange={e=>setForm({...form,color:e.target.value})}/></Field><Field label="Valor de aquisição"><input type="number" step="0.01" value={form.acquisition_value} onChange={e=>setForm({...form,acquisition_value:+e.target.value})}/></Field><Field label="Outros custos"><input type="number" step="0.01" value={form.other_costs} onChange={e=>setForm({...form,other_costs:+e.target.value})}/></Field></div><button className="primary" onClick={add}>+ Cadastrar veículo</button></section>{!createOnly&&<section className="panel"><PanelHead eyebrow="SUCATAS" title="Veículos cadastrados" text={`${data.length} registros`}/><Table rows={data} cols={['id','plate','brand','model','year','fuel','transmission','status','acquisition_value']} format={{acquisition_value:money}}/></section>}</>}

const productEmpty={sku:'',name:'',category:'',part_group:'',brand:'',model:'',year:'',oem:'',condition:'used',side:'',position:'',cost:0,price:0,stock:1,location_id:null,vehicle_id:null,description:'',compatibility:'',image_urls:'',weight:1,package_length:20,package_width:20,package_height:20,ml_category_id:'',ml_listing_type:'gold_special',shopee_category_id:'',shopee_logistic_id:'',shopee_image_ids:'',olx_category_id:'',publish_mercadolivre:true,publish_shopee:true,publish_olx:true,ml_has_warranty:false,ml_warranty_text:'',ml_shipping_mode:'',ml_free_shipping:false,ml_local_pickup:true,auto_publish:false}

function imageList(value){const v=value||'';return (v.includes('data:image/')?v.split(/\n/):v.split(/\n|,/)).map(x=>x.trim()).filter(Boolean)}
function readFileAsDataUrl(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)})}
function loadImage(src){return new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=reject;img.src=src})}
async function prepareProductImage(file,removeBg=true){
  const src=await readFileAsDataUrl(file),img=await loadImage(src),max=1200,scale=Math.min(1,max/Math.max(img.width,img.height)),w=Math.max(1,Math.round(img.width*scale)),h=Math.max(1,Math.round(img.height*scale));
  const canvas=document.createElement('canvas');canvas.width=w;canvas.height=h;const ctx=canvas.getContext('2d',{willReadFrequently:true});ctx.fillStyle='#fff';ctx.fillRect(0,0,w,h);ctx.drawImage(img,0,0,w,h);
  if(removeBg){
    const data=ctx.getImageData(0,0,w,h),d=data.data,pts=[[2,2],[w-3,2],[2,h-3],[w-3,h-3]].filter(([x,y])=>x>=0&&y>=0),bg=[0,0,0];
    pts.forEach(([x,y])=>{const i=(y*w+x)*4;bg[0]+=d[i];bg[1]+=d[i+1];bg[2]+=d[i+2]});bg.forEach((_,i)=>bg[i]/=Math.max(1,pts.length));
    const threshold=72;
    for(let i=0;i<d.length;i+=4){const dr=d[i]-bg[0],dg=d[i+1]-bg[1],db=d[i+2]-bg[2],dist=Math.sqrt(dr*dr+dg*dg+db*db);if(dist<threshold){const blend=Math.max(0,Math.min(1,(threshold-dist)/threshold));d[i]=Math.round(d[i]+(255-d[i])*blend);d[i+1]=Math.round(d[i+1]+(255-d[i+1])*blend);d[i+2]=Math.round(d[i+2]+(255-d[i+2])*blend)}}
    ctx.putImageData(data,0,0)
  }
  return canvas.toDataURL('image/jpeg',.84)
}

function MarketplaceConfigModal({market,form,setForm,onClose}){
  if(!market)return null
  return <div className="modalBackdrop" onMouseDown={e=>e.target===e.currentTarget&&onClose()}><div className="marketConfigModal"><div className="modalHead"><div><small>CONFIGURAÇÃO DO CANAL</small><h2>{marketName(market)}</h2><p>Preencha apenas o que esse marketplace precisa para publicar esta peça.</p></div><button className="iconClose" onClick={onClose}>×</button></div>
    {market==='mercadolivre'&&<div className="modalBody"><div className="optionGrid"><label className={'choiceCard '+(form.condition==='new'?'selected':'')}><input type="radio" name="cond" checked={form.condition==='new'} onChange={()=>setForm({...form,condition:'new'})}/><b>Novo</b><small>Peça sem uso.</small></label><label className={'choiceCard '+(form.condition==='used'?'selected':'')}><input type="radio" name="cond" checked={form.condition==='used'} onChange={()=>setForm({...form,condition:'used'})}/><b>Usado</b><small>Peça usada/desmontada.</small></label><label className={'choiceCard '+(form.condition==='reconditioned'?'selected':'')}><input type="radio" name="cond" checked={form.condition==='reconditioned'} onChange={()=>setForm({...form,condition:'reconditioned'})}/><b>Recondicionado</b><small>Peça revisada.</small></label></div><h3 className="formSectionTitle">Garantia</h3><div className="optionGrid two"><label className={'choiceCard '+(form.ml_has_warranty?'selected':'')}><input type="radio" checked={form.ml_has_warranty} onChange={()=>setForm({...form,ml_has_warranty:true})}/><b>Possui garantia</b><small>Informe a garantia abaixo.</small></label><label className={'choiceCard '+(!form.ml_has_warranty?'selected':'')}><input type="radio" checked={!form.ml_has_warranty} onChange={()=>setForm({...form,ml_has_warranty:false,ml_warranty_text:''})}/><b>Não possui garantia</b><small>Sem garantia associada.</small></label></div>{form.ml_has_warranty&&<Field label="Texto da garantia"><input placeholder="Ex.: 90 dias de garantia" value={form.ml_warranty_text} onChange={e=>setForm({...form,ml_warranty_text:e.target.value})}/></Field>}<h3 className="formSectionTitle">Listagem</h3><div className="optionGrid two"><label className={'choiceCard '+(form.ml_listing_type==='gold_pro'?'selected':'')}><input type="radio" checked={form.ml_listing_type==='gold_pro'} onChange={()=>setForm({...form,ml_listing_type:'gold_pro'})}/><b>Premium</b><small>Maior exposição quando disponível.</small></label><label className={'choiceCard '+(form.ml_listing_type==='gold_special'?'selected':'')}><input type="radio" checked={form.ml_listing_type==='gold_special'} onChange={()=>setForm({...form,ml_listing_type:'gold_special'})}/><b>Clássica</b><small>Listagem padrão.</small></label></div><h3 className="formSectionTitle">Frete</h3><div className="optionGrid three"><label className={'choiceCard '+(form.ml_shipping_mode===''?'selected':'')}><input type="radio" checked={form.ml_shipping_mode===''} onChange={()=>setForm({...form,ml_shipping_mode:''})}/><b>Automático</b><small>Usar configuração da conta/categoria.</small></label><label className={'choiceCard '+(form.ml_shipping_mode==='me2'?'selected':'')}><input type="radio" checked={form.ml_shipping_mode==='me2'} onChange={()=>setForm({...form,ml_shipping_mode:'me2'})}/><b>Mercado Envios</b><small>Quando elegível para a conta.</small></label><label className={'choiceCard '+(form.ml_shipping_mode==='custom'?'selected':'')}><input type="radio" checked={form.ml_shipping_mode==='custom'} onChange={()=>setForm({...form,ml_shipping_mode:'custom'})}/><b>A combinar</b><small>Frete combinado com o comprador.</small></label></div><div className="switchRows"><label><input type="checkbox" checked={form.ml_free_shipping} onChange={e=>setForm({...form,ml_free_shipping:e.target.checked})}/><span><b>Frete grátis</b><small>Marque somente se sua operação oferecer frete grátis.</small></span></label><label><input type="checkbox" checked={form.ml_local_pickup} onChange={e=>setForm({...form,ml_local_pickup:e.target.checked})}/><span><b>Retirada pessoalmente</b><small>Permitir retirada da peça na loja física.</small></span></label></div></div>}
    {market==='shopee'&&<div className="modalBody"><Field label="ID da categoria"><input value={form.shopee_category_id} onChange={e=>setForm({...form,shopee_category_id:e.target.value})}/></Field><Field label="ID de logística"><input value={form.shopee_logistic_id} onChange={e=>setForm({...form,shopee_logistic_id:e.target.value})}/></Field><Field label="IDs de imagens Shopee"><textarea value={form.shopee_image_ids} onChange={e=>setForm({...form,shopee_image_ids:e.target.value})}/></Field><p className="fieldHelp">Esses dados dependem da loja conectada na Shopee Open Platform.</p></div>}
    {market==='olx'&&<div className="modalBody"><Field label="ID da categoria OLX"><input value={form.olx_category_id} onChange={e=>setForm({...form,olx_category_id:e.target.value})}/></Field><p className="fieldHelp">A OLX também utiliza telefone e CEP cadastrados nas Informações da Empresa e exige conta/plano compatível com a integração.</p></div>}
    <div className="modalFoot"><button className="ghost" onClick={onClose}>Fechar</button><button className="primary" onClick={onClose}>Salvar configuração</button></div></div></div>
}

function ProductImages({form,setForm,notice}){
  const [removeBg,setRemoveBg]=useState(true),[busy,setBusy]=useState(false);const images=imageList(form.image_urls)
  async function upload(files){if(!files?.length)return;setBusy(true);try{const arr=[];for(const f of Array.from(files).slice(0,8)){if(!f.type.startsWith('image/'))continue;arr.push(await prepareProductImage(f,removeBg))}setForm({...form,image_urls:[...images,...arr].join('\n')});notice(`${arr.length} foto(s) adicionada(s)`)}catch(e){notice('Não foi possível processar a foto')}finally{setBusy(false)}}
  async function whiten(i){try{const value=images[i];const blob=await fetch(value).then(r=>r.blob());const file=new File([blob],`produto-${i}.jpg`,{type:blob.type||'image/jpeg'});const out=await prepareProductImage(file,true);const next=[...images];next[i]=out;setForm({...form,image_urls:next.join('\n')});notice('Fundo tratado e deixado branco')}catch(e){notice('Não foi possível tratar esta imagem')}}
  function remove(i){const next=images.filter((_,idx)=>idx!==i);setForm({...form,image_urls:next.join('\n')})}
  return <div className="imageEditor"><div className="imageUploadBar"><label className="uploadButton">＋ Adicionar fotos<input type="file" accept="image/*" multiple onChange={e=>upload(e.target.files)} disabled={busy}/></label><label className="tinyCheck"><input type="checkbox" checked={removeBg} onChange={e=>setRemoveBg(e.target.checked)}/><span>Remover fundo e deixar branco ao adicionar</span></label>{busy&&<small>Processando imagens...</small>}</div>{images.length>0&&<div className="imagePreviewGrid">{images.map((src,i)=><div className="imagePreview" key={i}><img src={src}/><div><button type="button" className="ghost" onClick={()=>whiten(i)}>Fundo branco</button><button type="button" className="dangerSmall" onClick={()=>remove(i)}>Remover</button></div></div>)}</div>}<details className="advancedUrls"><summary>Adicionar imagem por URL</summary><textarea placeholder="Uma URL pública por linha" value={form.image_urls} onChange={e=>setForm({...form,image_urls:e.target.value})}/></details></div>
}

function ProductForm({refresh,notice,groups=[],brands=[],vehicles=[],initialProduct=null,onClose=null}){
  const editing=!!initialProduct,[form,setForm]=useState({...productEmpty,...(initialProduct||{}),auto_publish:false}),[mlSuggestions,setMlSuggestions]=useState([]),[findingCategory,setFindingCategory]=useState(false),[marketModal,setMarketModal]=useState(null)
  useEffect(()=>{setForm({...productEmpty,...(initialProduct||{}),auto_publish:false})},[initialProduct?.id])
  async function suggestMl(){if(!form.name.trim())return notice('Informe o nome da peça primeiro');setFindingCategory(true);try{const r=await api.get('/marketplaces/mercadolivre/category-suggestions',{params:{q:`${form.name} ${form.brand} ${form.model}`.trim(),limit:3}});setMlSuggestions(r.data||[]);if(r.data?.[0])setForm(f=>({...f,ml_category_id:r.data[0].category_id}));notice(r.data?.length?'Categoria sugerida pelo Mercado Livre':'Nenhuma categoria encontrada')}catch(e){notice(e.response?.data?.detail||'Conecte o Mercado Livre para sugerir categoria')}finally{setFindingCategory(false)}}
  function chooseVehicle(id){const v=vehicles.find(x=>x.id===+id);if(!v){setForm({...form,vehicle_id:null});return}setForm({...form,vehicle_id:v.id,brand:v.brand||'',model:v.model||'',year:v.year||'',compatibility:form.compatibility||`${v.brand||''} ${v.model||''} ${v.year||''}`.trim()})}
  async function save(autoPublish=false){try{if(!form.sku.trim()||!form.name.trim())return notice('Informe SKU e nome da peça');const payload={...form,auto_publish:autoPublish,year:form.year?+form.year:null,vehicle_id:form.vehicle_id?+form.vehicle_id:null};if(editing)await api.put(`/products/${initialProduct.id}`,payload);else await api.post('/products',payload);await refresh();notice(editing?(autoPublish?'Peça atualizada e canais ativos processados':'Peça atualizada'):(autoPublish?'Peça cadastrada e canais ativos processados':'Peça cadastrada'));if(editing){onClose?.()}else setForm({...productEmpty})}catch(e){notice(e.response?.data?.detail||'Erro ao salvar a peça')}}
  const channel=(id,label,field,desc)=><div className={'channelToggle '+(form[field]?'enabled':'')}><div><MarketLogo id={id}/><span><b>{label}</b><small>{desc}</small></span></div><label className="switch"><input type="checkbox" checked={!!form[field]} onChange={e=>setForm({...form,[field]:e.target.checked})}/><i/></label><button type="button" className="ghost" disabled={!form[field]} onClick={()=>setMarketModal(id)}>Configurar</button></div>
  return <section className={editing?'productEditorBody':'panel'}><PanelHead eyebrow={editing?'EDIÇÃO':'CATÁLOGO'} title={editing?`Editar peça #${initialProduct.id}`:'Cadastro de Peças'} text={editing?'Altere os dados e salve no mesmo produto.':'Vincule a peça ao veículo de origem, adicione fotos e escolha em quais marketplaces publicar.'}/><h3 className="formSectionTitle">Origem e compatibilidade</h3><div className="formGrid products"><Field label="Veículo de origem" wide><select value={form.vehicle_id||''} onChange={e=>chooseVehicle(e.target.value)}><option value="">Sem vínculo / peça avulsa</option>{vehicles.map(v=><option key={v.id} value={v.id}>#{v.id} · {v.plate||'sem placa'} · {v.brand} {v.model} {v.year||''}</option>)}</select></Field><VehicleBrandModel form={form} setForm={setForm} brands={brands}/><Field label="Ano compatível"><input type="number" min="1971" max={new Date().getFullYear()+1} value={form.year||''} onChange={e=>setForm({...form,year:e.target.value})}/></Field></div><h3 className="formSectionTitle">Dados da peça</h3><div className="formGrid products"><Field label="SKU"><input value={form.sku||''} onChange={e=>setForm({...form,sku:e.target.value.toUpperCase()})}/></Field><Field label="Nome da peça"><input value={form.name||''} onChange={e=>setForm({...form,name:e.target.value})}/></Field><Field label="Categoria"><input value={form.category||''} onChange={e=>setForm({...form,category:e.target.value})}/></Field><Field label="Grupo"><select value={form.part_group||''} onChange={e=>setForm({...form,part_group:e.target.value})}><option value="">Selecione...</option>{groups.map(g=><option key={g.id}>{g.name}</option>)}</select></Field><Field label="Código OEM"><input value={form.oem||''} onChange={e=>setForm({...form,oem:e.target.value})}/></Field><Field label="Lado"><select value={form.side||''} onChange={e=>setForm({...form,side:e.target.value})}><option value="">Não se aplica</option><option>Direito</option><option>Esquerdo</option></select></Field><Field label="Posição"><select value={form.position||''} onChange={e=>setForm({...form,position:e.target.value})}><option value="">Não se aplica</option><option>Dianteira</option><option>Traseira</option><option>Superior</option><option>Inferior</option></select></Field><Field label="Preço"><input type="number" step="0.01" value={form.price||0} onChange={e=>setForm({...form,price:+e.target.value})}/></Field><Field label="Estoque"><input type="number" min="0" value={form.stock||0} onChange={e=>setForm({...form,stock:+e.target.value})}/></Field><Field label="Custo"><input type="number" step="0.01" value={form.cost||0} onChange={e=>setForm({...form,cost:+e.target.value})}/></Field><Field label="Condição"><select value={form.condition||'used'} onChange={e=>setForm({...form,condition:e.target.value})}><option value="used">Usado</option><option value="new">Novo</option><option value="reconditioned">Recondicionado</option></select></Field><Field label="Descrição" wide><textarea value={form.description||''} onChange={e=>setForm({...form,description:e.target.value})}/></Field><Field label="Compatibilidade" wide><textarea placeholder="Ex.: Toyota Corolla 2015 a 2019; Corolla Cross..." value={form.compatibility||''} onChange={e=>setForm({...form,compatibility:e.target.value})}/></Field></div><h3 className="formSectionTitle">Fotos do produto</h3><ProductImages form={form} setForm={setForm} notice={notice}/><h3 className="formSectionTitle">Onde publicar</h3><div className="channelToggles">{channel('mercadolivre','Mercado Livre','publish_mercadolivre','Ativar ou desativar esta peça no Mercado Livre.')}{channel('shopee','Shopee','publish_shopee','Ativar ou desativar esta peça na Shopee.')}{channel('olx','OLX','publish_olx','Ativar ou desativar esta peça na OLX.')}</div>{form.publish_mercadolivre&&<div className="mlQuick"><button type="button" className="ghost" onClick={suggestMl} disabled={findingCategory}>{findingCategory?'Buscando...':'Sugerir categoria do Mercado Livre'}</button>{mlSuggestions.length>0&&<select value={form.ml_category_id||''} onChange={e=>setForm({...form,ml_category_id:e.target.value})}>{mlSuggestions.map(x=><option key={x.category_id} value={x.category_id}>{x.category_name} · {x.category_id}</option>)}</select>}<input placeholder="ID da categoria MLB..." value={form.ml_category_id||''} onChange={e=>setForm({...form,ml_category_id:e.target.value})}/></div>}<h3 className="formSectionTitle">Peso e embalagem</h3><div className="dimensions"><Field label="Peso (kg)"><input type="number" step="0.01" value={form.weight||0} onChange={e=>setForm({...form,weight:+e.target.value})}/></Field><Field label="Comprimento (cm)"><input type="number" value={form.package_length||0} onChange={e=>setForm({...form,package_length:+e.target.value})}/></Field><Field label="Largura (cm)"><input type="number" value={form.package_width||0} onChange={e=>setForm({...form,package_width:+e.target.value})}/></Field><Field label="Altura (cm)"><input type="number" value={form.package_height||0} onChange={e=>setForm({...form,package_height:+e.target.value})}/></Field></div><div className="formActions">{editing&&<button className="ghost" onClick={onClose}>Cancelar</button>}<button className="ghost strong" onClick={()=>save(false)}>{editing?'Salvar alterações':'Salvar peça'}</button><button className="primary" onClick={()=>save(true)}>{editing?'Salvar e sincronizar canais ativos':'Salvar e publicar canais ativos →'}</button></div><MarketplaceConfigModal market={marketModal} form={form} setForm={setForm} onClose={()=>setMarketModal(null)}/></section>
}

function LabelPrintOverlay({products=[],company}){if(!products.length)return null;return <div className="printOverlay"><div className="printLabelSheet">{products.map(p=><div className="stockLabel" key={p.id}><div className="labelQr"><QRCodeSVG value={`${location.origin}/?produto=${p.id}&sku=${encodeURIComponent(p.sku||'')}`} size={122}/><small>{location.host}</small></div><div className="labelData"><b className="labelCompany">{company?.trade_name||'CDM DESMONTES'}</b><strong className="labelCode">{p.id}</strong><div className="labelDescription">{p.name}</div><div className="labelVehicle">{[p.brand,p.model,p.year].filter(Boolean).join(' ')}{p.oem?` · OEM ${p.oem}`:''}</div><div className="labelBottom"><span>{p.condition==='new'?'NOVO':'USADO'}</span><b>{p.sku}</b></div></div></div>)}</div></div>}

function Inventory({data,listings,refresh,notice,groups=[],brands=[],vehicles=[],company}){
  const [q,setQ]=useState(''),[limit,setLimit]=useState(12),[showFilters,setShowFilters]=useState(false),[selected,setSelected]=useState([]),[editing,setEditing]=useState(null),[printItems,setPrintItems]=useState([]),[view,setView]=useState('card');
  const rows=useMemo(()=>data.filter(p=>`${p.sku} ${p.name} ${p.brand} ${p.model}`.toLowerCase().includes(q.toLowerCase())).slice(0,limit),[data,q,limit]);
  async function publish(id){try{await api.post(`/marketplaces/products/${id}/publish-all`);await refresh();notice('Somente os canais ativos desta peça foram processados')}catch(e){notice(e.response?.data?.detail||'Erro ao publicar')}}
  async function removeSelected(){if(!selected.length)return;if(!confirm(`Arquivar ${selected.length} produto(s) selecionado(s)?`))return;try{for(const id of selected)await api.delete(`/products/${id}`);setSelected([]);await refresh();notice('Produtos arquivados')}catch(e){notice('Não foi possível excluir todos os produtos')}}
  function toggle(id){setSelected(s=>s.includes(id)?s.filter(x=>x!==id):[...s,id])}
  function printLabels(items){if(!items.length)return notice('Selecione pelo menos um produto');setPrintItems(items);setTimeout(()=>window.print(),180)}
  function exportCsv(){const csv=['SKU;Produto;Marca;Modelo;Preço;Estoque;Mercado Livre;Shopee;OLX',...data.map(p=>[p.sku,p.name,p.brand,p.model,p.price,p.stock,p.publish_mercadolivre?'SIM':'NÃO',p.publish_shopee?'SIM':'NÃO',p.publish_olx?'SIM':'NÃO'].join(';'))].join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='estoque-cdm.csv';a.click()}
  return <><div className="inventoryActions"><div><button className="labelBtn" disabled={!selected.length} onClick={()=>printLabels(data.filter(p=>selected.includes(p.id)))}>▣ Gerar Etiquetas ({selected.length})</button><button className="ghost" disabled={!selected.length} onClick={removeSelected}>🗑 Excluir Selecionados</button><button className="ghost" onClick={()=>setSelected(selected.length===rows.length?[]:rows.map(p=>p.id))}>{selected.length===rows.length&&rows.length?'Limpar seleção':'Selecionar visíveis'}</button></div><div><button className="ghost" onClick={()=>window.print()}>▤ Exportar PDF</button><button className="excelBtn" onClick={exportCsv}>↓ Exportar Excel</button></div></div><div className="inventoryViewBar"><span>Visualização em:</span><label><input type="radio" checked={view==='card'} onChange={()=>setView('card')}/> Card</label><label><input type="radio" checked={view==='list'} onChange={()=>setView('list')}/> Lista</label><span className="stockMode">◉ Estoque Atual</span></div><section className="panel inventoryPanel"><div className="inventoryToolbar"><label>Mostrando: <select value={limit} onChange={e=>setLimit(+e.target.value)}><option>12</option><option>24</option><option>48</option></select></label><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Pesquise pela Descrição, Marca ou Modelo"/><button className="filterBtn" onClick={()=>setShowFilters(!showFilters)}>⌁ Mais Filtros</button></div>{showFilters&&<div className="filterStrip"><span>Filtros avançados preparados para categoria, faixa de preço, localização e estoque.</span></div>}{view==='card'?<div className="productCards">{rows.map(p=><ProductCard key={p.id} p={p} listings={listings} publish={publish} selected={selected.includes(p.id)} toggle={()=>toggle(p.id)} edit={()=>setEditing(p)} print={()=>printLabels([p])}/>)}</div>:<div className="inventoryList">{rows.map(p=><div className={'inventoryRow '+(selected.includes(p.id)?'selected':'')} key={p.id}><input type="checkbox" checked={selected.includes(p.id)} onChange={()=>toggle(p.id)}/><div className="rowImage">{imageList(p.image_urls)[0]?<img src={imageList(p.image_urls)[0]}/>:<span>Sem foto</span>}</div><div className="rowGrow"><b>#{p.id} · {p.name}</b><small>{p.brand} {p.model} {p.year||''} · {p.sku}</small></div><strong>{money(p.price)}</strong><span>{p.stock} un.</span><button className="ghost" onClick={()=>setEditing(p)}>Editar</button><button className="ghost" onClick={()=>printLabels([p])}>Etiqueta</button></div>)}</div>}{!rows.length&&<div className="emptyState">Nenhuma peça encontrada.</div>}</section>{editing&&<div className="modalBackdrop editorBackdrop"><div className="productEditModal"><button className="iconClose floating" onClick={()=>setEditing(null)}>×</button><ProductForm initialProduct={editing} refresh={refresh} notice={notice} groups={groups} brands={brands} vehicles={vehicles} onClose={()=>setEditing(null)}/></div></div>}<LabelPrintOverlay products={printItems} company={company}/></>
}

function ProductCard({p,listings,publish,selected,toggle,edit,print}){const img=imageList(p.image_urls)[0];return <article className={'productCard '+(selected?'selected':'')}><label className="productSelect"><input type="checkbox" checked={selected} onChange={toggle}/></label><div className="cardTabs"><b>Dados</b><span title={p.compatibility||'Sem compatibilidade cadastrada'}>Compatibilidade</span></div><div className="productName"><strong>{p.id} - {p.name}</strong><small>{p.brand} {p.model} {p.year||''}</small></div><div className="productImage">{img?<img src={img}/>:<div className="noImage">PRODUTO<br/><b>SEM IMAGEM</b></div>}</div><div className="productMeta"><div><small>Preço</small><b>{money(p.price)}</b></div><div><small>Estoque</small><b>{p.stock} un.</b></div></div><ListingBadges product={p} listings={listings}/><div className="productActions"><button title="Editar produto" onClick={edit}>✎ <span>Editar</span></button><button title="Imprimir etiqueta" onClick={print}>▣ <span>Etiqueta</span></button><button title="Publicar / sincronizar" onClick={()=>publish(p.id)}>↻ <span>Publicar</span></button></div></article>}
function ListingBadges({product,listings}){const rows=listings.filter(x=>x.product_id===product.id);const enabled={mercadolivre:product.publish_mercadolivre,shopee:product.publish_shopee,olx:product.publish_olx};return <div className="badges">{['mercadolivre','shopee','olx'].map(m=>{const r=rows.find(x=>x.marketplace===m);return <span key={m} title={!enabled[m]?'Canal desativado para esta peça':r?.error_message||''} className={'mini '+(!enabled[m]?'off':r?.status==='published'?'ok':r?'warn':'')}>{m==='mercadolivre'?'ML':m==='shopee'?'SH':'OLX'} {!enabled[m]?'OFF':''}</span>})}</div>}


function CatalogModule({tab,data,refresh,notice}){if(tab==='tax')return <TaxConfig data={data.tax} refresh={refresh} notice={notice}/>;const cfg={customers:{title:'Clientes',endpoint:'customers',fields:['name','cpf_cnpj','phone','email','address']},suppliers:{title:'Fornecedores',endpoint:'suppliers',fields:['name','cpf_cnpj','phone','email']},carriers:{title:'Transportadoras',endpoint:'carriers',fields:['name','cnpj','phone','email']},sellers:{title:'Vendedores',endpoint:'sellers',fields:['name','email','phone','commission_rate']},'part-groups':{title:'Grupo de peças',endpoint:'part-groups',fields:['name','description']},locations:{title:'Localizações',endpoint:'locations',fields:['warehouse','aisle','shelf','bin']}}[tab];const arr=tab==='part-groups'?data.partGroups:data[tab]||[];return <GenericCrud cfg={cfg} rows={arr} refresh={refresh} notice={notice}/>}
function GenericCrud({cfg,rows,refresh,notice}){const initial=Object.fromEntries(cfg.fields.map(f=>[f,f==='commission_rate'?0:'']));const [form,setForm]=useState(initial);async function add(){try{await api.post(`/catalog/${cfg.endpoint}`,form);setForm(initial);await refresh();notice(`${cfg.title}: cadastro salvo`)}catch(e){notice(e.response?.data?.detail||'Erro ao salvar')}}return <section className="panel"><PanelHead eyebrow="CADASTROS" title={cfg.title} text="Cadastro separado por empresa e usuário."/><div className="formGrid">{cfg.fields.map(f=><Field key={f} label={pretty(f)}>{f==='description'||f==='address'?<textarea value={form[f]} onChange={e=>setForm({...form,[f]:e.target.value})}/>:<input type={f==='commission_rate'?'number':'text'} value={form[f]} onChange={e=>setForm({...form,[f]:f==='commission_rate'?+e.target.value:e.target.value})}/>}</Field>)}</div><button className="primary" onClick={add}>+ Salvar cadastro</button><Table rows={rows} cols={['id',...cfg.fields]}/></section>}
function TaxConfig({data,refresh,notice}){const [form,setForm]=useState(data||{regime:'Simples Nacional',crt:'1',cfop_default:'5102',ncm_default:'',csosn_default:'102',notes:''});useEffect(()=>data&&setForm(data),[data]);async function save(){await api.put('/catalog/tax',form);await refresh();notice('Configuração tributária salva')}return <section className="panel"><PanelHead eyebrow="FISCAL" title="Configuração Tributária" text="Defina os padrões fiscais da empresa."/><div className="formGrid">{['regime','crt','cfop_default','ncm_default','csosn_default'].map(k=><Field key={k} label={pretty(k)}><input value={form[k]||''} onChange={e=>setForm({...form,[k]:e.target.value})}/></Field>)}<Field label="Observações" wide><textarea value={form.notes||''} onChange={e=>setForm({...form,notes:e.target.value})}/></Field></div><button className="primary" onClick={save}>Salvar configuração</button></section>}

function LabelsModule({tab,products,company}){
  const [selected,setSelected]=useState([]),[printItems,setPrintItems]=useState([])
  function toggle(id){setSelected(s=>s.includes(id)?s.filter(x=>x!==id):[...s,id])}
  function printSelected(){const items=products.filter(p=>selected.includes(p.id));if(!items.length)return;setPrintItems(items);setTimeout(()=>window.print(),180)}
  return <><section className="panel"><PanelHead eyebrow="ETIQUETAS" title={tab==='label-models'?'Modelo padrão CDM':'Gerar Etiquetas'} text="Selecione as peças e imprima etiquetas com QR Code, código grande e aplicação do veículo."/><div className="labelToolbar"><button className="labelBtn" onClick={printSelected} disabled={!selected.length}>▣ Imprimir selecionadas ({selected.length})</button><button className="ghost" onClick={()=>setSelected(selected.length===products.length?[]:products.map(p=>p.id))}>{selected.length===products.length&&products.length?'Limpar seleção':'Selecionar todas'}</button></div>{tab==='label-models'&&<div className="labelModelInfo"><b>Etiqueta CDM 100 × 50 mm</b><span>Empresa + QR Code + código grande + descrição + veículo/OEM + SKU.</span></div>}<div className="labelGrid">{products.slice(0,36).map(p=><label className={'labelPreview '+(selected.includes(p.id)?'selected':'')} key={p.id}><input type="checkbox" checked={selected.includes(p.id)} onChange={()=>toggle(p.id)}/><QRCodeSVG value={`${location.origin}/?produto=${p.id}&sku=${encodeURIComponent(p.sku||'')}`} size={62}/><div><small>#{p.id} · {p.sku}</small><b>{p.name}</b><strong>{p.brand} {p.model} {p.year||''}</strong></div></label>)}</div></section><LabelPrintOverlay products={printItems} company={company}/></>
}

function Sales({products,sales,refresh,notice}){const [pid,setPid]=useState(''),[qty,setQty]=useState(1),[method,setMethod]=useState('pix');const selected=products.find(p=>p.id===+pid);async function sell(){try{await api.post('/sales',{payment_method:method,items:[{product_id:+pid,quantity:+qty}]});setPid('');await refresh();notice('Venda finalizada e estoque baixado')}catch(e){notice(e.response?.data?.detail||'Erro na venda')}}return <div className="twoCols saleLayout"><section className="panel"><PanelHead eyebrow="PDV" title="Nova Venda" text="Venda rápida com baixa automática no estoque."/><Field label="Produto"><select value={pid} onChange={e=>setPid(e.target.value)}><option value="">Selecione...</option>{products.filter(p=>p.stock>0).map(p=><option key={p.id} value={p.id}>{p.sku} — {p.name}</option>)}</select></Field>{selected&&<div className="saleProduct"><div><small>Produto</small><b>{selected.name}</b></div><div><small>Disponível</small><b>{selected.stock} un.</b></div><div><small>Valor</small><b>{money(selected.price)}</b></div></div>}<div className="formGrid"><Field label="Quantidade"><input type="number" min="1" value={qty} onChange={e=>setQty(e.target.value)}/></Field><Field label="Pagamento"><select value={method} onChange={e=>setMethod(e.target.value)}><option value="pix">PIX</option><option value="credit">Cartão</option><option value="cash">Dinheiro</option></select></Field></div><div className="saleTotal"><span>Total</span><strong>{money((selected?.price||0)*qty)}</strong></div><button className="primary bigBtn" disabled={!pid} onClick={sell}>Finalizar venda →</button></section><section className="panel"><PanelHead eyebrow="HISTÓRICO" title="Últimas vendas" text={`${sales.length} vendas`}/><Table rows={sales.slice(0,10)} cols={['id','payment_method','total','status','created_at']} format={{total:money}}/></section></div>}
function SalesHistory({sales}){return <section className="panel"><PanelHead eyebrow="VENDAS" title="Vendas Realizadas" text="Consulte as vendas registradas."/><Table rows={sales} cols={['id','payment_method','total','status','created_at']} format={{total:money}}/></section>}

function Marketplaces({data,listings,products,refresh,notice,focus,subscription}){const filtered=focus&&['mercadolivre','shopee','olx'].includes(focus)?data.filter(m=>m.id===focus):data;async function connect(m){try{const r=await api.get(`/marketplaces/${m}/authorize`);location.href=r.data.url}catch(e){notice(e.response?.data?.detail||'Não foi possível iniciar a conexão')}}async function remove(m){try{await api.delete(`/marketplaces/${m}/connection`);await refresh();notice(`${marketName(m)} desconectado`)}catch(e){notice('Erro ao desconectar')}}async function pub(id){try{await api.post(`/marketplaces/products/${id}/publish-all`);await refresh();notice('Publicação processada')}catch(e){notice(e.response?.data?.detail||'Erro ao publicar')}}async function diag(m){try{const r=await api.get(`/marketplaces/${m}/diagnostics`);const d=r.data;alert(`${marketName(m)}

Aplicação configurada: ${d.app_ready?'SIM':'NÃO'}
Conta conectada: ${d.connected?'SIM':'NÃO'}
Redirect URI: ${d.redirect_uri}
Status: ${d.status}
Último erro: ${d.last_error||'nenhum'}`)}catch(e){notice('Não foi possível executar o diagnóstico')}}return <><div className="pageTitle marketplaceTitle"><div><span>HUB DE VENDAS</span><h2>{focus&&['mercadolivre','shopee','olx'].includes(focus)?marketName(focus):'Integrações de Marketplaces'}</h2><p>Cada assinante conecta a própria conta. Você não precisa receber senha nem token do cliente.</p></div><span className={['active','trial'].includes(subscription?.status)?'statusBadge':'statusBadge bad'}>Plano: {subscription?.status||'—'}</span></div><div className="marketGrid">{filtered.map(m=><div className="marketCard" key={m.id}><MarketLogo id={m.id} large/><div className="marketBody"><h3>{marketName(m.id)}</h3><p>{marketDesc(m.id)}</p><div className="marketStats"><span><b>{m.published}</b> publicados</span><span><b>{m.processing||0}</b> processando</span><span><b>{m.issues}</b> pendências</span></div>{m.connected?<><div className="connection ready"><i/> Conectado: {m.account_name||m.external_account_id}</div><button className="ghost full" onClick={()=>remove(m.id)}>Desconectar conta</button></>:<><div className="connection"><i/> {m.app_ready?'Conta ainda não autorizada':'Aplicação precisa ser configurada no servidor'}</div><button className="primary full" disabled={!m.app_ready} onClick={()=>connect(m.id)}>Conectar {marketName(m.id)} →</button></>}{m.last_error&&<div className="marketError"><b>Último erro da conexão</b><span>{m.last_error}</span></div>}<button className="ghost full" onClick={()=>diag(m.id)}>Verificar configuração</button></div></div>)}</div><section className="panel info"><h3>Como funciona para seus clientes</h3><p>Você configura uma vez as credenciais da aplicação CDM no servidor. Depois, cada empresa assinante entra no próprio painel e clica em <b>Conectar</b>; o marketplace abre a autorização oficial e o token fica vinculado somente àquela empresa.</p><p className="muted">Se o Mercado Livre recusar a autorização, use “Verificar configuração”. O CDM mostra o Redirect URI que precisa ser idêntico ao cadastrado no painel do Mercado Livre e guarda o último erro sem exibir segredos.</p></section><section className="panel"><PanelHead eyebrow="PUBLICAÇÃO" title="Central de anúncios" text="Acompanhe o retorno por canal."/><div className="tableWrap"><table><thead><tr><th>Produto</th><th>Mercado Livre</th><th>Shopee</th><th>OLX</th><th>Ação</th></tr></thead><tbody>{products.map(p=><tr key={p.id}><td><b>{p.name}</b><small className="block">{p.sku}</small></td>{['mercadolivre','shopee','olx'].map(m=>{const r=listings.find(x=>x.product_id===p.id&&x.marketplace===m);return <td key={m}><Status r={r}/></td>})}<td><button className="ghost" onClick={()=>pub(p.id)}>Publicar em todos</button></td></tr>)}</tbody></table></div></section></>}

function Status({r}){if(!r)return <span className="pill neutral">Não enviado</span>;if(r.status==='published')return <span className="pill success">Publicado</span>;if(['processing','queued','pending'].includes(r.status))return <span className="pill neutral">Processando</span>;return <span className="pill warn" title={r.error_message}>{r.status==='needs_connection'?'Conectar conta':r.status==='needs_product_data'?'Completar produto':'Pendência'}</span>}
function MarketLogo({id,large}) {return <div className={'marketLogo '+id+(large?' large':'')}>{id==='mercadolivre'?'ML':id==='shopee'?'SH':'OLX'}</div>}

function FiscalModule({tab}){const map={invoices:['NF-e','Emissão de nota fiscal eletrônica'], 'invoice-history':['Notas Emitidas','Consulta e acompanhamento das notas emitidas'],xml:['Enviar XML','Envie e organize arquivos XML fiscais'],'invalidate-number':['Inutilizar número','Controle de inutilização de numeração fiscal'],notas:['Notas Fiscais','Central fiscal']};const [title,text]=map[tab]||map.notas;return <SimpleModule eyebrow="FISCAL" title={title} text={text} actions={['Nova operação','Consultar histórico','Configurações fiscais']}/>}
function Finance({data,refresh,notice}){const [form,setForm]=useState({kind:'income',description:'',amount:0,status:'paid',due_date:''});async function add(){await api.post('/finance',form);setForm({...form,description:'',amount:0});await refresh();notice('Lançamento salvo')}return <section className="panel"><PanelHead eyebrow="FINANCEIRO" title="Financeiro" text="Controle entradas e saídas."/><div className="formGrid"><Field label="Tipo"><select value={form.kind} onChange={e=>setForm({...form,kind:e.target.value})}><option value="income">Entrada</option><option value="expense">Saída</option></select></Field><Field label="Descrição"><input value={form.description} onChange={e=>setForm({...form,description:e.target.value})}/></Field><Field label="Valor"><input type="number" value={form.amount} onChange={e=>setForm({...form,amount:+e.target.value})}/></Field><Field label="Vencimento"><input value={form.due_date} onChange={e=>setForm({...form,due_date:e.target.value})}/></Field></div><button className="primary" onClick={add}>Salvar lançamento</button><Table rows={data} cols={['id','kind','description','amount','status','due_date']} format={{amount:money}}/></section>}
function CashFlow({data}){const income=data.filter(x=>x.kind==='income').reduce((a,x)=>a+Number(x.amount||0),0),expense=data.filter(x=>x.kind==='expense').reduce((a,x)=>a+Number(x.amount||0),0);return <><div className="grid three"><Card icon="↑" title="Entradas" value={money(income)} sub="Receitas"/><Card icon="↓" title="Saídas" value={money(expense)} sub="Despesas"/><Card icon="=" title="Saldo" value={money(income-expense)} sub="Posição atual"/></div><section className="panel"><PanelHead eyebrow="CAIXA" title="Fluxo de Caixa" text="Movimentações consolidadas."/><Table rows={data} cols={['id','kind','description','amount','status','due_date']} format={{amount:money}}/></section></>}
function Reports({products,sales,finance,vehicles}){const stockValue=products.reduce((a,p)=>a+Number(p.cost||0)*Number(p.stock||0),0),revenue=sales.reduce((a,s)=>a+Number(s.total||0),0),low=products.filter(p=>p.stock<=1).length;return <><div className="grid metrics"><Card icon="R$" title="Vendas acumuladas" value={money(revenue)} sub={`${sales.length} vendas`}/><Card icon="▤" title="Custo em estoque" value={money(stockValue)} sub={`${products.length} SKUs`}/><Card icon="!" title="Estoque baixo" value={low} sub="1 unidade ou menos"/><Card icon="🚗" title="Sucatas" value={vehicles.length} sub="Veículos"/></div><section className="panel"><PanelHead eyebrow="RELATÓRIOS" title="Estoque baixo" text="Itens que merecem atenção."/><Table rows={products.filter(p=>p.stock<=1)} cols={['sku','name','stock','price']} format={{price:money}}/></section></>}
function Gamification({sales,products}){const points=sales.length*10+products.length*2;return <section className="panel"><PanelHead eyebrow="EQUIPE" title="Gamificação" text="Metas e produtividade da equipe."/><div className="scoreHero"><small>PONTOS DA OPERAÇÃO</small><strong>{points}</strong><span>Nível {Math.max(1,Math.floor(points/100)+1)}</span><div className="progress"><i style={{width:`${Math.min(100,points%100)}%`}}/></div></div></section>}

function SimpleModule({eyebrow,title,text,actions=[]}){return <><div className="pageTitle"><div><span>{eyebrow}</span><h2>{title}</h2><p>{text}</p></div></div><div className="moduleCards">{actions.map((a,i)=><div className="moduleCard" key={a}><div className="moduleIcon">{['+','▤','⚙'][i%3]}</div><div><h3>{a}</h3><p>Módulo organizado e pronto para receber regras específicas.</p><span className="pill neutral">Disponível</span></div></div>)}</div></>}
function Checklist({items}){return <div className="checklist">{items.map(i=><span key={i}>✓ {i}</span>)}</div>}
function PanelHead({eyebrow,title,text}){return <div className="panelTitle"><div><small>{eyebrow}</small><h2>{title}</h2><p>{text}</p></div></div>}
function Field({label,children,wide}){return <label className={'field '+(wide?'wide':'')}><span>{label}</span>{children}</label>}
function Table({rows,cols,format={}}){return <div className="tableWrap"><table><thead><tr>{cols.map(c=><th key={c}>{pretty(c)}</th>)}</tr></thead><tbody>{rows?.length?rows.map((r,i)=><tr key={r.id||i}>{cols.map(c=><td key={c}>{format[c]?format[c](r[c]):String(r[c]??'')}</td>)}</tr>):<tr><td colSpan={cols.length} className="empty">Nenhum registro ainda.</td></tr>}</tbody></table></div>}
function pretty(s){return ({cpf_cnpj:'CPF / CNPJ',commission_rate:'Comissão %',cfop_default:'CFOP padrão',ncm_default:'NCM padrão',csosn_default:'CSOSN padrão',created_at:'Criado em',payment_method:'Pagamento',acquisition_value:'Valor aquisição'}[s]||s.replaceAll('_',' ')).replace(/^./,x=>x.toUpperCase())}
function marketName(id){return id==='mercadolivre'?'Mercado Livre':id==='shopee'?'Shopee':'OLX'}
function marketDesc(id){return id==='mercadolivre'?'O cliente autoriza a própria conta via OAuth e publica suas peças.':id==='shopee'?'A loja do cliente fica vinculada à empresa dele no CDM.':'Autorização OAuth e importação de anúncios para contas com plano compatível.'}

createRoot(document.getElementById('root')).render(<App/>)
